const body = $('Webhook Crear Corte').first().json.body;
const filas = $input.all().map(i => i.json);

const fecha_corte = String(body.fecha_corte || '').trim();
const genetica = String(body.genetica || '').trim();
const num_esquejes = parseInt(body.num_esquejes, 10);
const intervalo_dias = parseInt(body.intervalo_dias, 10) || 14;
const operario = String(body.operario || '').trim();
const observaciones = String(body.observaciones || '').trim();

if (!fecha_corte) throw new Error('falta fecha_corte');
if (!genetica) throw new Error('falta genetica');
if (!num_esquejes || num_esquejes <= 0) throw new Error('num_esquejes invalido');

const prefixMap = { 'Amnesia': 'AMN', 'Hokuzai': 'HOK' };
const prefix = prefixMap[genetica] || genetica.slice(0, 3).toUpperCase();

// Secuencial del dia para misma genetica
const mismoDia = filas.filter(f =>
  String(f.fecha_corte || '').trim() === fecha_corte &&
  String(f.genetica || '').trim() === genetica
);
const secuencial = mismoDia.length + 1;
const id_evento = prefix + '-' + fecha_corte + '-' + secuencial;

// Fecha proximo corte = fecha_corte + intervalo_dias
const d = new Date(fecha_corte + 'T00:00:00Z');
d.setUTCDate(d.getUTCDate() + intervalo_dias);
const fecha_proximo = d.getUTCFullYear() + '-' +
  String(d.getUTCMonth() + 1).padStart(2, '0') + '-' +
  String(d.getUTCDate()).padStart(2, '0');

return [{
  json: {
    id_evento,
    fecha_corte,
    genetica,
    num_esquejes,
    intervalo_dias,
    fecha_proximo_corte_estimada: fecha_proximo,
    operario,
    observaciones,
    estado: 'activo'
  }
}];

const evento = $('Preparar Evento').first().json;

// Calcular fecha = fecha_corte + N dias (UTC, mismo metodo que Preparar Evento)
function offsetDate(baseISO, days) {
  const d = new Date(baseISO + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.getUTCFullYear() + '-' +
    String(d.getUTCMonth() + 1).padStart(2, '0') + '-' +
    String(d.getUTCDate()).padStart(2, '0');
}

const trazabilidad = 'Generada por evento ' + evento.id_evento +
  ' (corte ' + evento.fecha_corte + ', ' + evento.num_esquejes + ' esquejes)';

// 4 tareas asociadas al lote — 3 mirando al esqueje + 1 a la madre
const tareas = [
  {
    offset_dias: 3,
    zona: 'esquejes',
    prioridad: 'media',
    tarea: 'Pulverizar bandejas lote ' + evento.id_evento + ' con Clonex Mist',
    observaciones: trazabilidad
  },
  {
    offset_dias: 6,
    zona: 'esquejes',
    prioridad: 'media',
    tarea: 'Pulverizar bandejas lote ' + evento.id_evento + ' con Formulez y Rhyzotonic',
    observaciones: 'Formulez 3ml/litro de agua y Rhyzo 4ml por litro de agua.'
  },
  {
    offset_dias: 9,
    zona: 'esquejes',
    prioridad: 'media',
    tarea: 'Sumergir bandejas lote ' + evento.id_evento + ' con Formulez y Rhyzotonic',
    observaciones: 'Formulez 3ml/litro de agua y Rhyzo 4ml por litro de agua. PH:5,8'
  },
  {
    offset_dias: evento.intervalo_dias,
    zona: 'madres',
    prioridad: 'alta',
    tarea: 'Evaluar vigor — proximo corte ' + evento.genetica,
    observaciones: trazabilidad
  }
];

// id unico por tarea: T + (timestamp+i) + 3 random — patron Crear_Tarea
// El +i garantiza unicidad aunque las 4 ejecuten en el mismo milisegundo
const baseTs = Date.now();
return tareas.map((t, i) => ({
  json: {
    id: 'T' + (baseTs + i) + String(Math.floor(Math.random() * 900 + 100)),
    zona: t.zona,
    tarea: t.tarea,
    prioridad: t.prioridad,
    estado: 'pendiente',
    fecha: offsetDate(evento.fecha_corte, t.offset_dias),
    recurrente: '',
    dia_recurrencia: '',
    observaciones: t.observaciones,
    id_evento_origen: evento.id_evento,
    tipo_origen: 'corte'
  }
}));

const eventos = $('Leer Eventos para Lista').all().map(i => i.json);
const reservas = $('Leer Reservas para Lista').all().map(i => i.json);

const reservasPorEvento = {};
for (const r of reservas) {
  const idEvento = String(r.id_evento || '').trim();
  if (!idEvento) continue;
  const estado = String(r.estado || '').trim().toLowerCase();
  if (estado === 'reservada' || estado === 'consumida') {
    if (!reservasPorEvento[idEvento]) reservasPorEvento[idEvento] = [];
    reservasPorEvento[idEvento].push(r);
  }
}

const items = eventos
  .map(f => {
    const id_evento = String(f.id_evento || '').trim();
    const num_esquejes = Number(f.num_esquejes) || 0;
    const n_descartados = Number(f.n_descartados) || 0;
    const total_neto = num_esquejes - n_descartados;
    const resList = reservasPorEvento[id_evento] || [];
    const reservado = resList.reduce((acc, r) => acc + (Number(r.cantidad) || 0), 0);
    const disponible = total_neto - reservado;
    return {
      id_evento,
      fecha_corte: String(f.fecha_corte || '').trim(),
      genetica: String(f.genetica || '').trim(),
      num_esquejes,
      intervalo_dias: Number(f.intervalo_dias) || 14,
      fecha_proximo_corte_estimada: String(f.fecha_proximo_corte_estimada || '').trim(),
      operario: String(f.operario || '').trim(),
      observaciones: String(f.observaciones || '').trim(),
      estado: String(f.estado || '').trim(),
      total_neto,
      reservado,
      disponible,
      reservas_activas: resList.map(r => ({
        id_reserva: String(r.id_reserva || '').trim(),
        id_pedido: String(r.id_pedido || '').trim(),
        cantidad: Number(r.cantidad) || 0,
        estado: String(r.estado || '').trim(),
        fecha_reserva: String(r.fecha_reserva || '').trim(),
      })),
    };
  })
  .filter(f => f.id_evento)
  .sort((a, b) => {
    if (b.fecha_corte !== a.fecha_corte) return b.fecha_corte.localeCompare(a.fecha_corte);
    return b.id_evento.localeCompare(a.id_evento);
  });

return [{ json: { items } }];

const eventos = $('Leer Eventos Disponibilidad').all().map(i => i.json);
const reservas = $('Leer Reservas Disponibilidad').all().map(i => i.json);

const trigger = $('Webhook Disponibilidad').first().json;
const geneticaFilter = String((trigger.query && trigger.query.genetica) || '').trim().toLowerCase();

const reservasPorEvento = {};
for (const r of reservas) {
  const idEvento = String(r.id_evento || '').trim();
  if (!idEvento) continue;
  const estado = String(r.estado || '').trim().toLowerCase();
  if (estado === 'reservada' || estado === 'consumida') {
    reservasPorEvento[idEvento] = (reservasPorEvento[idEvento] || 0) + (Number(r.cantidad) || 0);
  }
}

const items = eventos
  .map(f => {
    const id_evento = String(f.id_evento || '').trim();
    const estado = String(f.estado || '').trim().toLowerCase() || 'activo';
    const num_esquejes = Number(f.num_esquejes) || 0;
    const n_descartados = Number(f.n_descartados) || 0;
    const total_neto = num_esquejes - n_descartados;
    const reservado = reservasPorEvento[id_evento] || 0;
    return {
      id_evento,
      genetica: String(f.genetica || '').trim(),
      fecha_corte: String(f.fecha_corte || '').trim(),
      total_neto,
      reservado,
      disponible: total_neto - reservado,
      estado,
    };
  })
  .filter(e => e.id_evento)
  .filter(e => e.estado === 'activo')
  .filter(e => !geneticaFilter || e.genetica.toLowerCase() === geneticaFilter)
  .filter(e => e.disponible > 0)
  .sort((a, b) => (a.fecha_corte || '').localeCompare(b.fecha_corte || ''));

return [{ json: { items } }];
